"""1332 (#11, powers completion): Record-Coverage-v1318.ps1 with each character's native powers under the product controller
on the current build. Each power is granted by name (lab-only `coop_grant_named models/powers/...`, 1214cm, which also
selects it in the left hand with the native equip) and cast with the native left trigger; the checkpoint reload after
each case restores the inventory, powers and mana. The partner is checked from its power presentation state:
- Corvo (host source): blink (aim, release, arrive), dark vision (on, off), bend time (start, release), windblast,
  possession (aim at nothing, release), devouring swarm;
- Emily (client source): far reach (aim, release, travel), domino (aim, release with no target), doppelganger, mesmerize,
  shadow walk (enter, move, exit), dark vision (on, off).
Single-step plans are written with the unary comma (@(,@(...))): in 1332a @(@(...)) flattened into one array, so
those powers' LT was never pressed (power-cast-probe-v1334a-d confirm the casts work, product mode included).
Each cast must present the power on the partner (power weight > .5) for at least three samples, through at least two
phases where the native power has them, and recover (power weight back near zero).
Generated by make_coverage_v1332.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1318.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("[string]$Take='coverage-v1318c',[string]$Candidate='candidate-npc-combat-v1214cf',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('walk8','crouch8','sprint3','turns','startstop','stairs')",
    "[string]$Take='coverage-v1332a',[string]$Candidate='candidate-npc-combat-v1214cm',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('blink','darkvision','bendtime','windblast','possession','swarm','farreach','domino','doppelganger','mesmerize','shadowwalk')")
rep("# 1318 (#11, locomotion completion)", "# 1332 (#11, powers completion): Corvo's and Emily's native powers granted by name and cast natively in product mode.\n# Generated by make_coverage_v1332.py.\n# 1318 (#11, locomotion completion)")
# Each character casts only its own powers (darkvision is both).
rep("foreach($source in $Sources){foreach($case in $Cases){", "$corvoPowers=@('blink','darkvision','bendtime','windblast','possession','swarm');$emilyPowers=@('farreach','domino','doppelganger','mesmerize','shadowwalk','darkvision')\n foreach($source in $Sources){foreach($case in @($Cases|Where-Object {$_-in$(if($source-eq'host'){$corvoPowers}else{$emilyPowers})})){")
rep("$caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=23500;startstop=17500;stairs=17500}[$case]",
    "$caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=23500;startstop=17500;stairs=17500;blink=9000;darkvision=9000;bendtime=9500;windblast=8000;possession=9000;swarm=9000;farreach=9000;domino=9000;doppelganger=10000;mesmerize=9500;shadowwalk=12000}[$case]")
rep("""    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""",
    """    $powerNames=@{blink='models/powers/blink/blink.inventoryitem';darkvision='models/powers/darkvision/darkvision.inventoryitem';bendtime='models/powers/bendtime/bendtime.inventoryitem';windblast='models/powers/windblast/windblast.inventoryitem';possession='models/powers/possession/possession.inventoryitem';swarm='models/powers/devouring_swarm/devouring_swarm.inventoryitem';farreach='models/powers/grapple/grapple.inventoryitem';domino='models/powers/phantasmallink/phantasmal_link.inventoryitem';doppelganger='models/powers/doppelganger/doppelganger.inventoryitem';mesmerize='models/powers/mesmerize/mesmerize.inventoryitem';shadowwalk='models/powers/shadow_walk/shadow_walk.inventoryitem'}
    $powerPlans=@{
     blink=@(@(2600,'lt',1200),@(6000,'lt',250));darkvision=@(@(2600,'lt',250),@(6000,'lt',250));bendtime=@(@(2600,'lt',250),@(6200,'lt',250));
     windblast=@(,@(2600,'lt',250));possession=@(,@(2600,'lt',1600));swarm=@(,@(2600,'lt',250));
     farreach=@(,@(2600,'lt',1200));domino=@(,@(2600,'lt',1400));doppelganger=@(,@(2600,'lt',800));mesmerize=@(,@(2600,'lt',1200));
     shadowwalk=@(@(2600,'lt',250),@(4400,'move',1600),@(7600,'lt',250))}
    if($powerNames.ContainsKey($case)){$pp=$powerPlans[$case]
     if($step-eq0-and$t-ge700){C $source "coop_grant_named $($powerNames[$case])";& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 20 -Quick|Out-Null;$step=1}
     elseif($step-ge1-and$step-le$pp.Count-and$t-ge$pp[$step-1][0]){$d=$pp[$step-1]
      switch($d[1]){'lt'{& "$lab/Send-D2Input.ps1" -Role $source -LeftTrigger 255 -DurationMs $d[2]|Out-Null};'move'{& "$lab/Send-D2Input.ps1" -Role $source -LeftY 14000 -DurationMs $d[2]|Out-Null}}
      $segments.Add(@{ms=$t;power=$d[1];arg=$d[2]});$step++}}
    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""")
rep("""$samples.Add([pscustomobject]@{ms=$t;a=$mv.a;""",
    """$samples.Add([pscustomobject]@{ms=$t;powerVariant=$mv.powerVariant;powerWeight=$mv.powerWeight;powerEvent=$mv.powerEvent;powerAmount=$mv.powerAmount;a=$mv.a;""")
rep("""   if($case-eq'stairs'){C $peer 'coop_observer_camera off'""",
    """   if($powerNames.ContainsKey($case)){$row.grant=(S $source '.observer-camera.json').itemGrant.named;& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 0 -Quick|Out-Null
    $on=@($samples|Where-Object {[double]$_.powerWeight-gt.5});$row.powerSamples=$on.Count;$row.powerVariants=@($on|ForEach-Object {[int]$_.powerVariant}|Sort-Object -Unique)
    $row.recovered=@($samples|Where-Object {$_.ms-ge$caseMs-1200-and[double]$_.powerWeight-lt.05}).Count
    if($row.grant.result-notin'granted_named','named_power_equip_requested'){throw "Power grant $($row.grant.result)"}
    if($on.Count-lt3){throw "$case presented $($on.Count) samples (variants $($row.powerVariants-join ','))"};if(!$row.recovered){throw "$case did not recover"}
    $row.checks.Add("$case presented ($($on.Count) samples, variants $($row.powerVariants-join ',')) and recovered")}
   if($case-eq'stairs'){C $peer 'coop_observer_camera off'""")
rep("scope='Locomotion completion coverage (1318, #11): walks and crouch walks in 8 directions, sprint and diagonals, in-place turns by size, starts/stops and speed changes, stairs; both source roles, product controller, free camera; checked from the partner presentation state; fixture restored after every case.'",
    "scope='Powers coverage (1332, #11): Corvo (blink, dark vision, bend time, windblast, possession, swarm) and Emily (far reach, domino, doppelganger, mesmerize, shadow walk, dark vision) granted by name in product mode (lab only) and cast natively; checked from the partner presentation state; fixture restored after every case.'")
# Film every power from the close side-on free camera of the crouched-heavy case (2.8 m to the source's left, pitch 15):
# in 1332c the observer's own view from 9 m left the tether, the spirit and the marks too small to review.
powers = "'blink','darkvision','bendtime','windblast','possession','swarm','farreach','domino','doppelganger','mesmerize','shadowwalk'"
rep("}elseif($case-in'crouchheavy','mana'){", "}elseif($case-in'crouchheavy','mana'," + powers + "){")
rep("if($case-notin'kick','crouchheavy','note','mana','stairs'){& \"$PSScriptRoot/Set-ObserverPitch.ps1\"",
    "if($case-notin'kick','crouchheavy','note','mana','stairs'," + powers + "){& \"$PSScriptRoot/Set-ObserverPitch.ps1\"")
# Standing cases look nearly level (1330d: pitch 15 cut off the head and the aimed arm); the crouched heavy keeps 15.
rep("& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $peer -Pitch 15 -Quick|Out-Null", "& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $peer -Pitch $(if($case-in'crouchheavy','mana'){15}else{4}) -Quick|Out-Null")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1332.ps1').write_bytes(out.encode('utf-8'))
print('ok')
